package com.hsbc.cmb.hk.dbb.automation.framework.web.page.codegen.codegen;

/**
 * 产物标记常量（Page / Step / Assert 三类产物共用）。
 *
 * <p>{@code GENERATED_MARKER} 写入产物首行，用于<b>冲突检测</b>：重新生成时若目标文件无此标记，
 * 视为手写代码并拒绝覆盖（防止把业务已加工的代码冲掉）。
 *
 * <p>{@code FIELDS_BLOCK_*} 是 Page 类里的生成块边界（F-15）：再生成时只替换块内内容，
 * 块外的手写字段 / 方法 / 类级注解原样保留。
 */
public final class CodegenMarkers {

    /** 产物首行标记（{@code .java} 用 {@code //} 前缀，{@code .feature} 用 {@code #} 前缀）。 */
    public static final String GENERATED_MARKER = "GENERATED BY CodegenInspector V3";

    static final String FIELDS_BLOCK_BEGIN = "    // <generated:fields>";
    static final String FIELDS_BLOCK_END = "    // </generated:fields>";

    private CodegenMarkers() {}
}
